<template><div class="logo-loop" aria-label="Áreas atendidas pela Miniverso"><div class="logo-track"><span v-for="item in doubled" :key="item.key"><b>{{ item.label }}</b><small>{{ item.detail }}</small></span></div></div></template>
<script setup>import { computed } from 'vue'; const props=defineProps({items:{type:Array,default:()=>[]}}); const doubled=computed(()=>[...props.items,...props.items].map((item,index)=>({...item,key:`${item.label}-${index}`})));</script>
<style scoped>.logo-loop{overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent);border-block:1px solid #7ecce52c}.logo-track{display:flex;width:max-content;animation:loop 28s linear infinite}.logo-loop:hover .logo-track{animation-play-state:paused}.logo-track span{display:grid;gap:5px;min-width:220px;padding:22px 34px;border-right:1px solid #7ecce526;color:#dff7ff}.logo-track b{font-size:14px;font-weight:500}.logo-track small{color:#7fa7b8;font:9px var(--font-mono);text-transform:uppercase;letter-spacing:.1em}@keyframes loop{to{transform:translateX(-50%)}}@media(prefers-reduced-motion:reduce){.logo-track{animation:none;flex-wrap:wrap;width:auto}.logo-track span:nth-child(n+5){display:none}}</style>
